{
  "name": "实验数据记录器",
  "name_en": "Experiment Data Recorder",
  "manufacturer": "",
  "description": "一个非物理的软件记录组件，用于实验过程中创建保存目录、设置数据路径、记录变量值，并初始化、保存和关闭数据文件。",
  "description_en": "A non-physical software recorder component used during experiments to create storage folders, manage data paths, record variable values, and initialize, save, and close data files.",
  "tag_hints": [
    "data recording",
    "experiment file saving",
    "variable storage",
    "path management",
    "datafile initialization",
    "lab automation software"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭记录器并结束当前数据文件操作。",
      "description_en": "Close the recorder and end operations on the current data file."
    },
    {
      "action_name": "auto-createFolder",
      "description": "创建用于保存实验记录的文件夹。",
      "description_en": "Create a folder for saving experimental records."
    },
    {
      "action_name": "auto-getPath",
      "description": "获取当前数据保存路径。",
      "description_en": "Get the current data save path."
    },
    {
      "action_name": "auto-getValue",
      "description": "获取指定变量的记录值。",
      "description_en": "Get the recorded value of the specified variable."
    },
    {
      "action_name": "auto-getValueType",
      "description": "获取指定变量的值类型。",
      "description_en": "Get the value type of the specified variable."
    },
    {
      "action_name": "auto-getVariableList",
      "description": "获取当前可记录的变量列表。",
      "description_en": "Get the list of currently recordable variables."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化记录过程并创建数据文件。",
      "description_en": "Initialize the recording process and create the data file."
    },
    {
      "action_name": "auto-save",
      "description": "保存当前记录的数据。",
      "description_en": "Save the currently recorded data."
    },
    {
      "action_name": "auto-setPath",
      "description": "设置数据保存路径。",
      "description_en": "Set the data save path."
    },
    {
      "action_name": "auto-setValue",
      "description": "设置指定变量的记录值。",
      "description_en": "Set the recorded value of the specified variable."
    }
  ]
}

